describe('Document Language Declaration in HTML Tag', () => {
  beforeEach(() => {
    cy.visit('/document-language');
  });

  it('should display the correct document language in the HTML tag', () => {
    // Setup: intercept the API call to get document language
    cy.intercept('GET', '/api/document/language', {
      statusCode: 200,
      body: {
        language: 'en-US'
      }
    }).as('getDocumentLanguage');

    // Verify the page loads
    cy.get('[data-testid="page-title"]').should('be.visible').should('contain', 'Document Language');

    // Wait for the API call to complete
    cy.wait('@getDocumentLanguage');

    // Verify the document language is declared in the HTML tag
    cy.get('[data-testid="html-tag"]').should('contain', '<html lang="en-US">');

    // Verify the language attribute is present in the body tag
    cy.get('[data-testid="body-tag"]').should('contain', 'lang="en-US"');

    // Verify the language is displayed in a language selector dropdown
    cy.get('[data-testid="language-selector"]').should('be.visible');
    cy.get('[data-testid="language-selector"]').should('contain', 'English (United States)');

    // Verify the page content is localized
    cy.get('[data-testid="content-section"]').should('be.visible');
    cy.get('[data-testid="content-section"]').should('contain', 'Welcome to our document');
  });

  it('should handle document language change and update HTML tag', () => {
    // Setup: intercept the API call to change document language
    cy.intercept('POST', '/api/document/language', {
      statusCode: 200,
      body: {
        language: 'fr-FR'
      }
    }).as('changeDocumentLanguage');

    // Verify initial language is set
    cy.get('[data-testid="html-tag"]').should('contain', '<html lang="en-US">');

    // Change the language via API call
    cy.get('[data-testid="language-selector"]').click();
    cy.get('[data-testid="fr-FR-option"]').click();

    // Wait for the API call to complete
    cy.wait('@changeDocumentLanguage');

    // Verify the HTML tag reflects the new language
    cy.get('[data-testid="html-tag"]').should('contain', '<html lang="fr-FR">');

    // Verify the language attribute is updated in the body tag
    cy.get('[data-testid="body-tag"]').should('contain', 'lang="fr-FR"');

    // Verify the language selector reflects the new language
    cy.get('[data-testid="language-selector"]').should('contain', 'French (France)');

    // Verify the page content is now localized in French
    cy.get('[data-testid="content-section"]').should('be.visible');
    cy.get('[data-testid="content-section"]').should('contain', 'Bienvenue sur notre document');
  });
});
